const frame=document.getElementById('app'),out=document.getElementById('results'),results=[];
const wait=ms=>new Promise(r=>setTimeout(r,ms));
async function until(fn){for(let i=0;i<250;i++){if(fn())return;await wait(20);}throw new Error('Timed out waiting for editor');}
await until(()=>frame.contentDocument?.getElementById('loading')?.hidden);
const win=frame.contentWindow,doc=frame.contentDocument,$=id=>doc.getElementById(id);let blobs=[];
// This regression harness exercises the download fallback. Direct-file handlers
// have their own API-backed browser harness in storage.html.
win.showOpenFilePicker=undefined;win.showSaveFilePicker=undefined;
const create=win.URL.createObjectURL.bind(win.URL);win.URL.createObjectURL=blob=>{blobs.push(blob);return create(blob);};
// Exercise the real export handlers without generating repeated OS downloads in this test page.
const anchorClick=win.HTMLAnchorElement.prototype.click;
win.HTMLAnchorElement.prototype.click=function(){if(!this.download)anchorClick.call(this);};
const fetchLocal=win.fetch.bind(win);win.fetch=(url,...args)=>{if(new URL(url,win.location.href).origin!==win.location.origin)throw new Error('External network access unavailable');return fetchLocal(url,...args);};
function assert(ok,message){if(!ok)throw new Error(message);}
async function test(name,fn){try{await fn();results.push({name,pass:true});}catch(e){results.push({name,pass:false,error:e.message});}out.textContent=JSON.stringify(results,null,2);}
function click(id){$(id).click();}
async function discardPrompt(){await wait(20);if($('file-dialog').open){[...doc.querySelectorAll('#file-dialog-actions button')].find(b=>b.textContent==='Discard changes')?.click();await wait(20);}}
async function newForTest(){click('btn-new');await discardPrompt();await until(()=>!doc.querySelector('.diagram-node,.diagram-zone,.diagram-edge'));}
function input(id,value){$(id).value=value;$(id).dispatchEvent(new win.Event('input',{bubbles:true}));}
function change(id,value){$(id).value=value;$(id).dispatchEvent(new win.Event('change',{bubbles:true}));}
function key(key,extra={}){$('viewport').dispatchEvent(new win.KeyboardEvent('keydown',{key,bubbles:true,...extra}));}
async function saved(){const previous=blobs.length;click('btn-save');assert(blobs.length>previous,'save produced a project blob');return JSON.parse(await blobs.at(-1).text());}
async function apply(source){input('editor',source);click('btn-apply');await until(()=>$('loading').hidden);}
function hitNode(id,shiftKey=false){const n=doc.querySelector(`.diagram-node[data-object-id="${id}"] .node-shape`),b=n.getBoundingClientRect();n.dispatchEvent(new win.PointerEvent('pointerdown',{bubbles:true,isPrimary:true,button:0,pointerId:1,clientX:b.x+b.width/2,clientY:b.y+b.height/2,shiftKey}));$('viewport').dispatchEvent(new win.PointerEvent('pointerup',{bubbles:true,isPrimary:true,button:0,pointerId:1,clientX:b.x+b.width/2,clientY:b.y+b.height/2}));}
// Pointer capture needs a native pointer in normal use. Synthetic gestures in this harness
// use an inert capture implementation; native capture and dragging are also tested via the UI.
const viewport=$('viewport');viewport.setPointerCapture=()=>{};viewport.hasPointerCapture=()=>false;
function pointer(type,x,y,target=$('canvas'),extra={}){target.dispatchEvent(new win.PointerEvent(type,{bubbles:true,isPrimary:true,button:0,pointerId:2,clientX:x,clientY:y,...extra}));}
const source='flowchart LR\n subgraph Outer[Outer zone]\n subgraph Inner[Inner zone]\n A[Alpha]\n B(Beta)\n end\n end\n C[(Database)]\n A one@-->|reads| B\n B two@--> C';
await test('source import replaces structure and preserves nested hierarchy',async()=>{await apply(source);const m=await saved();assert(m.nodes.length===3&&m.edges.length===2&&m.zones.length===2,'all objects');assert(m.nodes.find(n=>n.id==='A').parentId==='Inner','nested membership');});
await test('dragging the title overlay moves its whole zone once and undo restores it',async()=>{
 const before=await saved(),backing=doc.querySelector('.zone-title[data-object-id="Outer"] .zone-label-backing'),b=backing.getBoundingClientRect();
 const opacity=Number(win.getComputedStyle(backing).fillOpacity);assert(opacity>0&&opacity<1,'live title backing is translucent');
 pointer('pointerdown',b.x+b.width/2,b.y+b.height/2,backing);pointer('pointermove',b.x+b.width/2+40,b.y+b.height/2+25,viewport);await wait(40);pointer('pointerup',b.x+b.width/2+40,b.y+b.height/2+25,viewport);
 const after=await saved(),dx=40/before.settings.view.scale,dy=25/before.settings.view.scale;
 for(const old of [...before.zones,...before.nodes.filter(n=>n.parentId==='Inner')]){const moved=[...after.zones,...after.nodes].find(n=>n.id===old.id);assert(Math.abs(moved.x-old.x-dx)<.01&&Math.abs(moved.y-old.y-dy)<.01,'descendant moved once: '+old.id);}
 assert(JSON.stringify(after.nodes.find(n=>n.id==='C'))===JSON.stringify(before.nodes.find(n=>n.id==='C')),'external node stays fixed');
 click('btn-undo');assert(JSON.stringify(await saved())===JSON.stringify(before),'undo restores full geometry and view');key('Escape');
});
await test('invalid drafts preserve diagram and history, and typing never relayouts',async()=>{const before=await saved();input('editor','flowchart TD\n A[broken');assert(JSON.stringify((await saved()).nodes)===JSON.stringify(before.nodes),'typing leaves nodes');click('btn-apply');await until(()=>$('loading').hidden);assert(!$('error-banner').hidden,'error shown');assert($('editor').value.includes('broken'),'draft retained');assert(JSON.stringify((await saved()).nodes)===JSON.stringify(before.nodes),'invalid source leaves valid diagram');click('btn-discard');});
await test('adding and editing a node preserves ID and updates generated source',async()=>{doc.querySelector('[data-tool="node"]').click();const b=$('canvas').getBoundingClientRect();pointer('pointerdown',b.x+80,b.y+180);change('property-label','New decision "quoted" 中文');change('property-shape','diamond');const m=await saved(),n=m.nodes.find(n=>n.id==='Node1');assert(n?.shape==='diamond'&&n.label.includes('中文'),'new node properties');assert($('editor').value.includes('Node1{'),'generated shape');});
await test('shape labels fit measured text, including long and wide glyphs',async()=>{change('property-label','MMMMMMMMMMMMMMMMMMMMMMMM\n中文中文中文中文中文中文中文');for(const shape of ['rectangle','rounded','diamond','circle','cylinder']){change('property-shape',shape);const node=doc.querySelector('[data-object-id="Node1"]'),shapeBox=node.querySelector('.node-shape').getBBox(),text=node.querySelector('text').getBBox();assert(text.x>=shapeBox.x&&text.y>=shapeBox.y&&text.x+text.width<=shapeBox.x+shapeBox.width&&text.y+text.height<=shapeBox.y+shapeBox.height,'text fits '+shape);}});
await test('parent changes visibly relocate objects and deleting zones retains contents',async()=>{const before=await saved(),original=before.nodes.find(n=>n.id==='Node1');change('property-parent-zone','Inner');let m=await saved(),n=m.nodes.find(n=>n.id==='Node1');assert(n.parentId==='Inner','reparent');assert(n.x!==original.x||n.y!==original.y,'parent change moves the node');assert(!doc.getElementById('btn-group')&&!doc.getElementById('btn-ungroup'),'group commands removed');key('Escape');const row=doc.querySelector('[data-tree-id="Inner"] .tree-object');row.click();click('btn-delete');m=await saved();assert(!m.zones.some(z=>z.id==='Inner'),'zone removed');assert(m.nodes.filter(n=>n.parentId==='Outer').length===3,'contents retained');click('btn-undo');});
await test('multi-selection alignment, distribution and grid nudges are undoable',async()=>{key('Escape');hitNode('A');hitNode('B',true);hitNode('Node1',true);change('alignment','left');let m=await saved(),selected=m.nodes.filter(n=>['A','B','Node1'].includes(n.id));assert(selected.every(n=>Math.abs(n.x-selected[0].x)<.01),'aligned');change('alignment','distribute-y');m=await saved();const arranged=m.nodes.filter(n=>['A','B','Node1'].includes(n.id)).sort((a,b)=>a.y-b.y);const gaps=arranged.slice(1).map((n,i)=>n.y-(arranged[i].y+arranged[i].height));assert(Math.abs(gaps[0]-gaps[1])<.01,'distributed');$('snap-grid').checked=true;$('snap-grid').dispatchEvent(new win.Event('change',{bubbles:true}));m=await saved();key('ArrowRight');const nudged=await saved();assert(nudged.nodes.find(n=>n.id==='A').x===m.nodes.find(n=>n.id==='A').x+20,'grid nudge');click('btn-undo');assert((await saved()).nodes.find(n=>n.id==='A').x===m.nodes.find(n=>n.id==='A').x,'undo nudge');click('btn-redo');assert((await saved()).nodes.find(n=>n.id==='A').x===m.nodes.find(n=>n.id==='A').x+20,'redo nudge');});
await test('zone creation, resizing, naming and deletion retain contents and title bounds',async()=>{key('Escape');doc.querySelector('[data-tool="zone"]').click();const b=$('canvas').getBoundingClientRect();pointer('pointerdown',b.x+120,b.y+220);change('property-label','A zone title that must stay inside its resized box');change('property-width','160');let m=await saved(),z=m.zones.find(z=>z.id==='Zone1');assert(z&&z.width>160,'title expands minimum size');assert(Number($('property-width').value)===Math.round(z.width),'inspector shows actual constrained size');change('property-parent-zone','Outer');assert((await saved()).zones.find(z=>z.id==='Zone1').parentId==='Outer','nested new zone');click('btn-delete');assert(!(await saved()).zones.some(z=>z.id==='Zone1'),'zone deleted');click('btn-undo');assert((await saved()).zones.some(z=>z.id==='Zone1'),'undo zone deletion');click('btn-delete');});
await test('edge properties, endpoints, loops and parallel connections update without relayout',async()=>{key('Escape');const edge=doc.querySelector('[data-object-id="one"] .edge-hit');pointer('pointerdown',1,1,edge);const before=(await saved()).nodes;change('property-label','Updated edge');change('property-direction','both');change('property-line-style','dashed');change('property-target','A');let m=await saved(),e=m.edges.find(e=>e.id==='one');assert(e.target==='A'&&e.direction==='both'&&e.style==='dashed','edited loop');assert(JSON.stringify(m.nodes)===JSON.stringify(before),'nodes stayed put');change('property-target','B');change('property-routing','straight');assert(doc.querySelector('[data-edge-id="one"]').getAttribute('d').split(' L').length===2,'straight connection');change('property-routing','orthogonal');});
await test('source application retains manual centres and unsupported imports do not replace the diagram',async()=>{const before=await saved();const evolved=$('editor').value.replace('Alpha','Changed alpha')+'\n Extra[Extra node]\n';await apply(evolved);const after=await saved();const a=before.nodes.find(n=>n.id==='A'),b=after.nodes.find(n=>n.id==='A');assert(Math.abs(a.x+a.width/2-b.x-b.width/2)<.01&&Math.abs(a.y+a.height/2-b.y-b.height/2)<.01,'manual centre retained');assert(after.nodes.some(n=>n.id==='Extra'),'new source node');await apply('sequenceDiagram\n A->>B: unsupported');assert(!$('error-banner').hidden,'unsupported error');assert((await saved()).nodes.length===after.nodes.length,'last diagram retained');click('btn-discard');});
await test('layout preferences and draft edits preserve positions; explicit layout is undoable',async()=>{const before=await saved();change('direction','BT');change('layout-mode','hierarchical');assert(JSON.stringify((await saved()).nodes)===JSON.stringify(before.nodes),'preferences do not relayout');input('editor',$('editor').value+'%% Keep this draft\n');const draft=$('editor').value;click('btn-layout');await until(()=>$('loading').hidden);assert($('editor').value===draft,'layout preserves draft');const laidOut=await saved();assert(JSON.stringify(laidOut.nodes)!==JSON.stringify(before.nodes),'explicit layout changed positions');click('btn-undo');assert(JSON.stringify((await saved()).nodes)===JSON.stringify(before.nodes),'undo restores arrangement');assert($('editor').value===draft,'undo preserves draft');click('btn-discard');});
