await test('save/open restores exact geometry and settings without relayout',async()=>{const original=await saved();key('Escape');hitNode('A');key('ArrowDown',{shiftKey:true});const transfer=new win.DataTransfer();transfer.items.add(new win.File([JSON.stringify(original)],'saved.json',{type:'application/json'}));$('file-input').files=transfer.files;$('file-input').dispatchEvent(new win.Event('change',{bubbles:true}));await discardPrompt();await until(()=>$('loading').hidden);assert($('file-state').textContent!=='Unsaved changes','opened saved project starts clean');assert(JSON.stringify(await saved())===JSON.stringify(original),'project fully restored');});
await test('SVG, PNG and Mermaid exports use the current model and exclude handles',async()=>{for(const format of ['svg','png','mermaid']){$('export-format').value=format;let length=blobs.length;click('btn-export');await until(()=>blobs.length>length);if(format==='png')await until(()=>blobs.at(-1).type==='image/png');const blob=blobs.at(-1);if(format==='png'){assert(blob.size>1000,'PNG contains image');const bytes=new Uint8Array(await blob.arrayBuffer());assert(bytes.slice(0,8).join(',')==='137,80,78,71,13,10,26,10','PNG signature');}else{const text=await blob.text();assert(format==='svg'?text.includes('viewBox=')&&!text.includes('editor-only'):text.includes('flowchart BT'),'valid export '+format);}}});
